R(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN CAST(selling_price AS FLOAT64) ELSE 0 END AS return_sales, cancelled_quantity, cast(null AS string) AS new_customer_flag, cast(null AS string) AS acquisition_product, null AS days_in_shipment, null AS acquisition_date, item_sku_code AS SKU_CODE, customer_gstin, coalesce(case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_name) else UPPER(p.PRODUCT_name) end,fi.item_type_name) AS PRODUCT_NAME_Final, upper(coalesce(case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_code) else UPPER(p.commonsku) end,fi.item_sku_code)) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.mrp, upper(case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.category_name) else upper(p.category) end) AS Product_category, coalesce(pmt.type,pm.type) as type from Maplemonk.unicommerce_myhyuman_get_b2b_sale_orders fi LEFT JOIN ( SELECT product_code AS commonsku, cast(null as string) as color_sku, product_code as parent_sku, PRODUCT_name, category, CAST(NULL AS STRING) AS product_sub_category, CAST(NULL AS STRING) AS image_url, MRP FROM `hyuman-wh.maplemonk.Final_sku_master` ) p ON LOWER(fi.item_sku_code) = LOWER(p.commonsku) left join (select product_code, type from ( select product_code, type, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1) pm on lower(pm.product_Code) = lower(fi.item_sku_code) left join (select * from ( select product_code, type, name as product_name, Brand, category_name, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1 ) pmt on upper(pmt.product_code) = upper(fi.item_sku_code) qualify row_number() over (partition by display_order_code,Sale_Order_Item_Code order by FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss)) desc) = 1 ;",
